import React from 'react';
import { Swiper, SwiperSlide } from 'swiper/react';
import { Pagination, Navigation, Autoplay, Scrollbar } from 'swiper/modules';
import 'swiper/css';
import 'swiper/css/navigation';
import 'swiper/css/pagination';
// 이미지 import
import slide1 from './images/slide1.jpg';
import slide2 from './images/slide2.jpg';
import slide3 from './images/slide3.jpg';
import slide4 from './images/slide4.jpg';
import './css/Slide.css';

function Slide() {
  return (
    <>
      <section className='slide_wrap'>
        <h2>메인슬라이드</h2> 
        <Swiper
          modules={[Navigation, Pagination, Scrollbar, Autoplay]}
          spaceBetween={0}
          slidesPerView={1}
          navigation
          autoplay={{ delay: 3000 }}
          pagination={{ clickable: true }}
          scrollbar={{ draggable: true }}
          className="mslide"
        >
          <SwiperSlide>
            <img src={slide1} alt="슬라이드 이미지 1" />
          </SwiperSlide>

          <SwiperSlide>
            <img src={slide2} alt="슬라이드 이미지 2" />
          </SwiperSlide>

          <SwiperSlide>
            <img src={slide3} alt="슬라이드 이미지 3" />
          </SwiperSlide>

          <SwiperSlide>
            <img src={slide4} alt="슬라이드 이미지 4" />
          </SwiperSlide>
        </Swiper>
      </section>
    </>
  );
}

export default Slide;
