import { Link } from 'react-router';
import Logo from '../assets/images/logo.png'
// 폰트어썸
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faMapMarkerAlt } from '@fortawesome/free-solid-svg-icons';
import { faHeart } from '@fortawesome/free-regular-svg-icons';
import { faCartShopping } from '@fortawesome/free-solid-svg-icons';
import { faMagnifyingGlass } from '@fortawesome/free-solid-svg-icons';
import { faBars } from '@fortawesome/free-solid-svg-icons';

// css
import '../assets/css/Header.css'

function Header() {
  return (
    <header>
      {/* 상단 헤더 */}
      <div className="header-top">
        <div className="header-inner">

          {/* 로고 및 쇼핑몰 메뉴 */}
          <div className="header-logo">
            <h1>
              <Link to='/'><img src={Logo} alt="로고" /></Link>
            </h1>

            <ul className="logo-menu">
              <li>
                <Link to="/">마켓컬리</Link>
              </li>
              <li>
                <Link to="/beauty">뷰티컬리</Link>
              </li>
            </ul>
          </div>

          {/* 검색창 */}
          <div className="header-search">
            <input
              type="text"
              placeholder="검색어를 입력해주세요"
              id='search'
            />
            <label for='search'><FontAwesomeIcon icon={faMagnifyingGlass} /></label>
          </div>

          {/* 아이콘 메뉴 */}
          <div className="header-icons">
            <ul>
              <li><Link to='/'><FontAwesomeIcon icon={faMapMarkerAlt} /></Link></li>
              <li><Link to='/'><FontAwesomeIcon icon={faHeart} /></Link></li>
              <li><Link to='/'><FontAwesomeIcon icon={faCartShopping} /></Link></li>
            </ul>
          </div>

        </div>

        {/* 회원 메뉴 */}
        <div className="header-member">
          <ul>
            <li><Link to="/join">회원가입</Link></li>
            <li><Link to="/login">로그인</Link></li>
            <li><Link to="/customer">고객센터</Link></li>
          </ul>
        </div>
      </div>

      {/* 하단 네비게이션 */}
      <nav className="header-nav">

        {/* 카테고리 */}
        <div className="category">
          <button type="button"><FontAwesomeIcon icon={faBars} /></button>
          <span>카테고리</span>
        </div>

        {/* 메뉴 목록 */}
        <ul className="nav-menu">
          <li><Link to="/best">베스트</Link></li>
          <li><Link to="/sale">세일</Link></li>
          <li><Link to="/fashion">패션</Link></li>
          <li><Link to="/living">리빙</Link></li>
          <li><Link to="/new">신상</Link></li>
          <li><Link to="/benefit">특가/혜택</Link></li>
        </ul>

        {/* 배송 안내 */}
        <div className="delivery-info">
          <Link to="/delivery"><span>샛별·하루</span> 배송안내</Link>
        </div>

      </nav>
    </header>
  );
}

export default Header;
