import React from 'react'
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faCartShopping } from '@fortawesome/free-solid-svg-icons';
import { faAngleRight } from '@fortawesome/free-solid-svg-icons';
import Feature1 from './images/feature1.jpg';
import Feature2 from './images/feature2.jpg';
import Feature3 from './images/feature3.jpg';
import Feature4 from './images/feature4.jpg';
import './css/Feature.css';

function Feature() {
  return (
    <>
<section className="Feature">
          <h2>🛒지금 가장 많이 담는 특가 <FontAwesomeIcon icon={faAngleRight} /></h2>
          <p className="sub_title">가장 인기있는 상품만 모아보세요!</p>
          <ul>
            <li>
              <img src={Feature1} alt=''/>
              <span className='coupon'>+10% 쿠폰</span>
              <button>
                <FontAwesomeIcon icon={faCartShopping} /> 담기
              </button>
              <div className='F_info'>
                <span className='F_info_name'>[톰볼라] 볼로네제 파스타</span>
                <span className='F_info_price'>22,900원</span>
                <span className='F_info_sale'>15%</span>
                <span className='F_info_totalPrice'>19,465원</span>
                <span className='F_info_kurlyOnly'>Kurly Only</span>
              </div>
            </li>

            <li>
              <img src={Feature2} alt=''/>
              <span className='coupon'>+15% 쿠폰</span>
              <button>
                <FontAwesomeIcon icon={faCartShopping} /> 담기
              </button>
              <div className='F_info'>
                <span className='F_info_name'>[남도우애] 무항생제 1++ 한우 등심 구이용 200g (냉장)</span>
                <span className='F_info_price'>39,600원</span>
                <span className='F_info_sale'>40%</span>
                <span className='F_info_totalPrice'>23,580원</span>
                <span className='F_info_kurlyOnly'>Kurly Only</span>
              </div>
            </li>

            <li>
              <img src={Feature3} alt=''/>
              <span className='coupon'>최대 +10% 쿠폰</span>
              <button>
                <FontAwesomeIcon icon={faCartShopping} /> 담기
              </button>
              <div className='F_info'>
                <span className='F_info_name'>[KF365] 대추방울토마토 750g</span>
                <span className='F_info_price'>9,900원</span>
                <span className='F_info_sale'>28%</span>
                <span className='F_info_totalPrice'>7,191원</span>
                <span className='F_info_kurlyOnly'>Kurly Only</span>
              </div>
            </li>

            <li>
              <img src={Feature4} alt=''/>
              <span className='members'>맴버스특가</span>
              <button>
                <FontAwesomeIcon icon={faCartShopping} /> 담기
              </button>
              <div className='F_info'>
                <span className='F_info_name'>[말콤] 퍼퓸 모이스트필 바디워시 1000mL 2종 (택1)</span>
                <span className='F_info_price'>32,000원</span>
                <span className='F_info_sale'>65%</span>
                <span className='F_info_totalPrice'>10,900원</span>
                <span className='F_info_kurlyOnly'>Kurly Only</span>
              </div>
            </li>
          </ul>
        </section>
    </>
  )
}

export default Feature