import React, { useState } from 'react'
import { Link, useNavigate } from 'react-router'

// css
import '../pages/css/Login.css'

function Login() {
  const navigate = useNavigate();

  const [id, setId] = useState();
  const [pw, setPw] = useState();

  const idChange=(e)=> {
    setId(e.target.value);
  };

  const pwChange=(e)=> {
    setPw(e.target.value);
  };

  const Logincheck=()=> {
    if (id === '1234' && pw === '1234') {
    alert('로그인 성공');
    navigate('/');
    } else {
      alert('로그인 실패! 다시 로그인해주세요.');
    }
  };

  return (
    <>
      <main>
        <section className='login_wrap'>
          <h2>로그인</h2>
          <form>
            <input
              id='id_box'
              type='text'
              placeholder='아이디를 입력해주세요.'
              value={id} 
              onChange={idChange}
            />

            <input
              id='pw_box'
              type='password'
              placeholder='비밀번호를 입력해주세요.'
              value={pw} 
              onChange={pwChange}
            />

            <div className='find'>
              <Link to='/'>아이디 찾기</Link>
              <span>|</span>
              <Link to='/'>비밀번호 찾기</Link>
            </div>

            <button type='button' className='login_btn' onClick={Logincheck}>
              로그인
            </button>

            <button
              type='button'
              className='join_btn'
              onClick={() => navigate('/join')}
            >
              회원가입
            </button>

            <h2>간편로그인</h2>

            {/* 네이버 로그인 */}
            <button type='button' className='naver_loginbtn'>
              <svg xmlns="http://www.w3.org/2000/svg" width="16" height="14" viewBox="0 0 16 14" fill="none"><g clip-path="url(#clip0_24020_117094)"><path d="M10.52 7.49L5.28165 0H0.94165V14H5.49165V6.51L10.7183 14H15.0583V0H10.52V7.49Z" fill="var(--kpds_ldmw171v)"></path></g><defs><clipPath id="clip0_24020_117094"><rect width="14.1167" height="14" fill="var(--kpds_ldmw171v)" transform="translate(0.94165)"></rect></clipPath></defs></svg>
              네이버로 계속하기
            </button>

            {/* 카카오 로그인 */}
            <button type='button' className='kakao_loginbtn'>
              <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none"><path d="M3.16016 10.6264C3.16016 13.16 4.7886 15.3759 7.23126 16.6468L6.40501 19.82C6.37295 19.9152 6.39628 20.0208 6.46517 20.0924C6.51422 20.1395 6.5786 20.1659 6.64566 20.1667C6.70162 20.1634 6.75506 20.1417 6.79808 20.1048L10.3518 17.6289C10.8752 17.7064 11.4033 17.7464 11.9321 17.7486C16.7733 17.7486 20.704 14.5547 20.704 10.6181C20.704 6.68148 16.7733 3.5 11.9321 3.5C7.08687 3.5 3.16016 6.68973 3.16016 10.6264Z" fill="var(--kpds_ldmw171t)"></path></svg>
              카카오로 계속하기
            </button>

          </form>
        </section>
      </main>
    </>
  )
}

export default Login
