import React from 'react'
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faCartShopping } from '@fortawesome/free-solid-svg-icons';
import BestProduct1 from './images/best1.jpg';
import BestProduct2 from './images/best2.jpeg';
import BestProduct3 from './images/best3.jpg';
import BestProduct4 from './images/best4.jpg';
import BestProduct5 from './images/best5.jpg';
import './css/BestProduct.css';

function BestProduct() {
  return (
    <>
<section className="bestProduct">
          <h2>실시간 인기 랭킹</h2>
          <p className="sub_title">가장 인기있는 상품만 모아보세요!</p>
          <ul>
            <li>
              <img src={BestProduct1} alt=''/>
              <div className="info">
                <span className="rank">1</span>
                <span className="product_name">
                  [비비고] 순살 생선구이 6종 (택1)
                </span>
                <span className="sale">9%</span>
                <span className="price">4,980원~</span>
                <button>
                  <FontAwesomeIcon icon={faCartShopping} /> 담기
                </button>
              </div>
            </li>

            <li>
              <img src={BestProduct2} alt=''/>
              <div className="info">
                <span className="rank">2</span>
                <span className="product_name">
                  [Dole] 스위티오 바나나 2종 (택1)
                </span>
                <span className="sale">5%</span>
                <span className="price">3,990원~</span>
                <button>
                  <FontAwesomeIcon icon={faCartShopping} /> 담기
                </button>
              </div>
            </li>

            <li>
              <img src={BestProduct3} alt=''/>
              <div className="info">
                <span className="rank">3</span>
                <span className="product_name">
                  [이연복의 목란] 짬뽕 2인분 (맵기선택)
                </span>
                <span className="sale">15%</span>
                <span className="price">12,325원~</span>
                <button>
                  <FontAwesomeIcon icon={faCartShopping} /> 담기
                </button>
              </div>
            </li>

            <li>
              <img src={BestProduct4} alt=''/>
              <div className="info">
                <span className="rank">4</span>
                <span className="product_name">
                  [KF 365] 양념 소불고기 4종 (택1)
                </span>
                <span className="sale">28%</span>
                <span className="price">14,310원~</span>
                <button>
                  <FontAwesomeIcon icon={faCartShopping} /> 담기
                </button>
              </div>
            </li>

            <li>
              <img src={BestProduct5} alt=''/>
              <div className="info">
                <span className="rank">5</span>
                <span className="product_name">
                  [KF 365] 당도선별 제주감귤 2.5kg (로얄과)
                </span>
                <span className="sale">44%</span>
                <span className="price">13,900원~</span>
                <button>
                  <FontAwesomeIcon icon={faCartShopping} /> 담기
                </button>
              </div>
            </li>
          </ul>
        </section>
    </>
  )
}

export default BestProduct