
import React from 'react'
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faMagnifyingGlass, faAngleRight } from '@fortawesome/free-solid-svg-icons'
import './css/Join.css'

function Join() {
  return (
    <>
      <main>
        <section className='Joinpage'>
          <h2>회원가입</h2>
          <p>필수입력사항</p>

          <div className='j_formWrap'>
            <form>

              <div className='j_id_box'>
                <span>아이디</span>
                <input type='text' placeholder='아이디를 입력해주세요' />
              </div>

              <div className='j_pw_box'>
                <span>비밀번호</span>
                <input type='password' placeholder='비밀번호를 입력해주세요' />
              </div>

              <div className='j_name_box'>
                <span>이름</span>
                <input type='text' placeholder='이름 입력해주세요' />
              </div>

              <div className='j_email_box'>
                <span>이메일</span>
                <div className='email_wrap'>
                  <input type='text' placeholder='이메일 입력해주세요' />
                  <span>@</span>
                  <select Value="">
                    <option value="">선택하세요</option>
                    <option value="naver.com">naver.com</option>
                    <option value="daum.net">daum.net</option>
                    <option value="gmail.com">gmail.com</option>
                  </select>
                </div>
              </div>

              <div className='j_phone_box'>
                <span>휴대폰</span>
                <input type='text' placeholder='휴대폰 입력해주세요' />
                <button>인증번호 받기</button>
              </div>

              <div className='j_address_box'>
                <span>주소</span>
                <button type='button'>
                  <FontAwesomeIcon icon={faMagnifyingGlass} />
                  주소 검색
                </button>
              </div>

              <div className='j_gender_box'>
                <span>성별</span>
                <div>
                  <label>
                    <input type='radio' name='gender' value='남자' />
                    남자
                  </label>

                  <label>
                    <input type='radio' name='gender' value='여자' />
                    여자
                  </label>

                  <label>
                    <input type='radio' name='gender' value='선택안함' />
                    선택안함
                  </label>
                </div>
              </div>

              <div className='j_birth_box'>
                <span>생년월일</span>
                <input type='text' placeholder='생년월일 입력해주세요' />
              </div>

              <div className='j_friend_box'>
                <span>추천인</span>
                <div>
                  <label>
                    <input type='radio' name='friend' value='' />
                    친구초대 추천인 아이디
                  </label>
                </div>
              </div>

              <hr />

              <p>이용약관동의</p>

              {/* 전체 동의 */}
              <div className='agree_all'>
                <label>
                  <input type='checkbox' />
                  <span>전체 동의합니다</span>
                </label>

                <p>
                  선택 항목에 동의하지 않은 경우도 회원가입 및
                  일반적인 서비스를 이용할 수 있습니다.
                </p>
              </div>

              {/* 컬리 이용약관 */}
              <div className='j_info'>
                <label>
                  <input type='checkbox' />
                  <span>컬리 이용약관 동의</span>
                  <span className='must'>(필수)</span>
                </label>

                <span>
                  <FontAwesomeIcon icon={faAngleRight} className='arrow' />
                </span>
              </div>

              {/* 개인정보 수집 및 이용 */}
              <div className='j_info'>
                <label>
                  <input type='checkbox' />
                  <span>개인정보 수집·이용</span>
                  <span className='must'>(필수)</span>
                </label>

                <span>
                  <FontAwesomeIcon icon={faAngleRight} className='arrow' />
                </span>
              </div>

              {/* 이벤트 및 혜택정보 */}
              <div className='j_info'>
                <label>
                  <input type='checkbox' />
                  <span>이벤트 및 혜택정보 발송을 위한 수집·이용</span>
                  <span className='must'>(선택)</span>
                </label>

                <span>
                  <FontAwesomeIcon icon={faAngleRight} className='arrow' />
                </span>
              </div>

              {/* 광고성 정보 수신 */}
              <div className='j_info'>
                <label>
                  <input type='checkbox' />
                  <span>광고성 정보 수신</span>
                  <span className='must'>(선택)</span>
                </label>
              </div>

              {/* 광고 수신 방법 */}
              <div className='ad_check'>
                <label>
                  <input type='checkbox' />
                  <span>문자</span>
                </label>

                <label>
                  <input type='checkbox' />
                  <span>이메일</span>
                </label>

                <label>
                  <input type='checkbox' />
                  <span>카카오</span>
                </label>
              </div>

              {/* 만 14세 이상 */}
              <div className='j_info age_check'>
                <label>
                  <input type='checkbox' />
                  <span>본인은 만 14세 이상입니다.</span>
                  <span className='must'>(필수)</span>
                </label>
              </div>
              <button type='button' className='done'>가입하기</button>
            </form>
          </div>
        </section>
      </main>
    </>
  )
}

export default Join
